  "detailHtml": "<p>Traditional系列的万能刷（极小号）。<br>\r\n采用高级科林斯基毛作为原毛，具有优雅的弹性。<br>\r\n此外，笔尖非常纤细，也适合精细作业，使用起来非常方便。<br>\r\n&nbsp;</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>形状</th>\r\n<td>\r\n<p>圆头</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>柯林斯基</td>\r\n</tr>\r\n<tr>\r\n<th>毛长</th>\r\n<td>21.2mm</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>206.2mm</td>\r\n</tr>\r\n</tbody>\r\n</table>",
