  "desc": "超人气Flower系列推出特别花型刷，线上首次登场！ 此前一直作为活动限定商品销售，因口碑相传而咨询蜂拥而至的一款刷子。 可从4种刷杆中选择您喜欢的花型刷。",
  "detail": "超人气Flower系列推出特别花型刷，线上首次登场！ 此前一直作为活动限定商品销售，因口碑相传而咨询蜂拥而至的一款刷子。 可从4种刷杆中选择您喜欢的花型刷。 形状 花型 毛质 染色山羊毛（粗光峰） 毛长 38mm Flower系列的花型蜜粉＆腮红刷。 采用山羊毛中最高级的粗光峰。抓粉力好，有挺度，触感格外出众。 ※染色色调可能与图片颜色不完全一致。",
  "detailHtml": "<p>超人气Flower系列推出特别花型刷，线上首次登场！<br>\r\n此前一直作为活动限定商品销售，因口碑相传而咨询蜂拥而至的一款刷子。<br>\r\n可从4种刷杆中选择您喜欢的花型刷。&nbsp;<br>\r\n&nbsp;</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>形状</th>\r\n<td>\r\n<p>花型</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>染色山羊毛（粗光峰）</td>\r\n</tr>\r\n<tr>\r\n<th>毛长</th>\r\n<td>38mm</td>\r\n</tr>\r\n</tbody>\r\n</table>\n<div>\r\n                    <p>Flower系列的花型蜜粉＆腮红刷。<br>\r\n采用山羊毛中最高级的粗光峰。抓粉力好，有挺度，触感格外出众。<br>\r\n※染色色调可能与图片颜色不完全一致。</p>\r\n\r\n                </div>",
