  "desc": "泡沫丰富的花型洁面刷，非常适合日常护肤。 采用优质山羊毛的花型洁面刷可用于整个面部，也可用于颈部/锁骨部位。 使用后请将刷子充分冲洗干净并去除水分，放在通风良好的地方晾干。",
  "detail": "泡沫丰富的花型洁面刷，非常适合日常护肤。 采用优质山羊毛的花型洁面刷可用于整个面部，也可用于颈部/锁骨部位。 使用后请将刷子充分冲洗干净并去除水分，放在通风良好的地方晾干。 形状 花型 毛质 山羊毛/合成纤维 出 锋 38mm 全长 68mm 刷毛柔软，温和洗净肌肤， 连毛孔深处的污垢也能彻底清除！ 如果您正为毛孔污垢和肌肤暗沉烦恼，也许是因为污垢没有彻底洗净！ 为了清除手洗无法洗净的污垢，用刷子很有效！ 用刷子充分打出细腻泡沫，在泡沫上用刷子清洗，既能彻底清除毛孔污垢，又不会过度清洁，对肌肤刺激小，实现美肌洁面/美肌身体清洁。 保养方法 （1）首先将笔尖上的泡沫/洁面产品充分冲洗干净。 （2）从笔尖根部向毛尖方向，充分挤干水分。 （拧的时候不要扭转，否则会导致掉毛，请将毛捋直后挤干。） （3）握住刷杆部分，将笔尖残留的水甩掉。 笔尖可能会散开，但无需整理形状。 （4）放在毛巾等上面晾干。（最好放在避免直射阳光、通风良好的阴凉处） ※注意事项 如果保持湿润状态，或沾有泡沫/洁面产品放置不管，会滋生霉菌，并导致断毛/掉毛/异味。 想要长久使用，使用后的保养很重要",
  "detailHtml": "<p>泡沫丰富的花型洁面刷，非常适合日常护肤。<br>\n采用优质山羊毛的花型洁面刷可用于整个面部，也可用于颈部/锁骨部位。<br>\n使用后请将刷子充分冲洗干净并去除水分，放在通风良好的地方晾干。<br>\n&nbsp;</p>\n\n<table class=\"sstable\">\n<tbody>\n<tr>\n<th>形状</th>\n<td>\n<p>花型</p>\n</td>\n</tr>\n<tr>\n<th>毛质</th>\n<td>山羊毛/合成纤维</td>\n</tr>\n<tr>\n<th>出　锋</th>\n<td>38mm</td>\n</tr>\n<tr>\n<th>全长</th>\n<td>68mm</td>\n</tr>\n</tbody>\n</table>\n<div>\r\n                    <h2><span style=\"font-size: 20px;\">刷毛柔软，温和洗净肌肤，<br>\r\n连毛孔深处的污垢也能彻底清除！</span></h2>\r\n\r\n<p><br>\r\n如果您正为毛孔污垢和肌肤暗沉烦恼，也许是因为污垢没有彻底洗净！<br>\r\n<br>\r\n为了清除手洗无法洗净的污垢，用刷子很有效！<br>\r\n用刷子充分打出细腻泡沫，在泡沫上用刷子清洗，既能彻底清除毛孔污垢，又不会过度清洁，对肌肤刺激小，实现美肌洁面/美肌身体清洁。<br>\r\n&nbsp;</p>\r\n\r\n<h3>保养方法</h3>\r\n\r\n<div style=\"text-align: left;\">（1）首先将笔尖上的泡沫/洁面产品充分冲洗干净。<br>\r\n（2）从笔尖根部向毛尖方向，充分挤干水分。<br>\r\n　　（拧的时候不要扭转，否则会导致掉毛，请将毛捋直后挤干。）<br>\r\n（3）握住刷杆部分，将笔尖残留的水甩掉。<br>\r\n　　 &nbsp;笔尖可能会散开，但无需整理形状。<br>\r\n（4）放在毛巾等上面晾干。（最好放在避免直射阳光、通风良好的阴凉处）<br>\r\n&nbsp;</div>\r\n\r\n<p><span style=\"color: rgb(255, 0, 0);\"><strong>※注意事项</strong></span></p>\r\n\r\n<p>如果保持湿润状态，或沾有泡沫/洁面产品放置不管，会滋生霉菌，并导致断毛/掉毛/异味。</p>\r\n\r\n<p>想要长久使用，使用后的保养很重要</p>\r\n<br>\r\n&nbsp;\r\n                </div>",
  "handle": "koyudo-000000000102",
  "level1": "护肤与清洁",
  "dimensions": {
   "series": [
    "花型洁面刷"
   ]
  }
