  "desc": "花朵洁面刷与专用刷架组成的套装。 非常适合日常护肤，也适合作为礼物！ 请从樱花、山茶花两种款式中选择。 刷架颜色为蓝色。",
  "detail": "花朵洁面刷与专用刷架组成的套装。 非常适合日常护肤，也适合作为礼物！ 请从樱花、山茶花两种款式中选择。 刷架颜色为蓝色。 形状 花型 毛质 山羊毛/聚酯纤维 毛长 38mm 全长 68mm 可从2种刷子中选择您喜欢的款式。 ① 樱花 ② 山茶花 泡沫丰富的花型洁面刷，搭配专用刷架组成套装。 采用优质山羊毛的花型洁面刷可用于整个面部，也可用于颈部/锁骨部位。 使用后请将化妆刷充分冲洗干净并去除水分，然后放在通风良好的地方，将刷头朝下放置晾干。",
  "detailHtml": "<p>花朵洁面刷与专用刷架组成的套装。<br>\r\n非常适合日常护肤，也适合作为礼物！<br>\r\n请从樱花、山茶花两种款式中选择。<br>\r\n刷架颜色为蓝色。<br>\r\n&nbsp;</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>形状</th>\r\n<td>\r\n<p>花型</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>山羊毛/聚酯纤维</td>\r\n</tr>\r\n<tr>\r\n<th>毛长</th>\r\n<td>38mm</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>68mm</td>\r\n</tr>\r\n</tbody>\r\n</table>\n<div>\r\n                    <p><span style=\"color: rgb(255, 0, 0);\"><strong>可从2种刷子中选择您喜欢的款式。</strong></span></p>\r\n\r\n<p><strong>①　樱花<br>\r\n②　山茶花</strong><br>\r\n&nbsp;</p>\r\n\r\n<p>泡沫丰富的花型洁面刷，搭配专用刷架组成套装。<br>\r\n采用优质山羊毛的花型洁面刷可用于整个面部，也可用于颈部/锁骨部位。<br>\r\n使用后请将化妆刷充分冲洗干净并去除水分，然后放在通风良好的地方，将刷头朝下放置晾干。</p>\r\n\r\n                </div>",
