  "desc": "可为购买的化妆刷刻名。 打造专属于您的原创化妆刷！ 为对方刻上姓名，作为礼物更显高级！ 刻名提供4种类型。 ①字母（连笔体） ②字母（印刷体） ③汉字 ④平假名",
  "detail": "可为购买的化妆刷刻名。 打造专属于您的原创化妆刷！ 为对方刻上姓名，作为礼物更显高级！ 刻名提供4种类型。 ①字母（连笔体） ②字母（印刷体） ③汉字 ④平假名",
  "detailHtml": "<p>可为购买的化妆刷刻名。<br>\r\n打造专属于您的原创化妆刷！<br>\r\n为对方刻上姓名，作为礼物更显高级！<br>\r\n刻名提供4种类型。</p>\r\n\r\n<p><strong>　①字母（连笔体）<br>\r\n　②字母（印刷体）<br>\r\n　③汉字<br>\r\n　④平假名</strong></p>",
