  "desc": "以果园送来的果实为意象的“可爱”熊野笔 也非常适合作为礼物！ 以蓝莓为意象的高光刷。刷杆采用重硬且耐冲击的胡桃木。圆形的刷子抓粉力好，非常适合打造眼部的立体感。 ※包装盒可从品牌设计的普通 “纸盒” 和可选的特制 “桐木盒（+330日元含税）” 两种中选择。 ※此商品无法提供刻名服务。",
  "detail": "以果园送来的果实为意象的“可爱”熊野笔 也非常适合作为礼物！ 以蓝莓为意象的高光刷。刷杆采用重硬且耐冲击的胡桃木。圆形的刷子抓粉力好，非常适合打造眼部的立体感。 ※包装盒可从品牌设计的普通 “纸盒” 和可选的特制 「桐木盒（＋ 由中国经济产业局主办，与研究机构和设计师合作，以“可爱之物”为理念进行商品开发的“可爱之物研究会”。 somell garden正是在这一举措中，源自当地广岛女性设计师的以下提案而诞生。 彩妆产品的名称中，使用了许多桃子、橙子等果实的名字。 那么，如果给化妆刷也加入果实的意象呢？比如，能以仿佛用脸颊轻蹭果实般的心情将刷子触碰肌肤……如果能像“染花”一样将果实的颜色印染在肌肤上……。 或许就能制作出带着这样美好心情每天早晨化妆的刷子。 不仅呈现出如果实染就般的自然色彩，例如桃子是中央凹陷的心形，蓝莓是紧凑圆润的刷尖，在确保易用性的基础上，笔尖形状也各自以果实为意象进行设计。 刷杆根据每种果实的颜色搭配相应的天然木材。 为了让温暖不仅传达给脸部，也温柔地传递给双手，我们对刷杆的触感也精益求精。 从作为化妆刷生命的原毛筛选开始，追求极致肌肤触感，采用机械生产无法实现的不剪毛尖工艺，每一支都手工制作。。",
  "detailHtml": "<p><span style=\"color: rgb(255, 0, 0);\"><strong>以果园送来的果实为意象的“可爱”熊野笔</strong></span></p>\r\n\r\n<p><span style=\"color: rgb(255, 0, 0);\"><strong>也非常适合作为礼物！</strong></span></p>\r\n\r\n<p>以蓝莓为意象的高光刷。刷杆采用重硬且耐冲击的胡桃木。圆形的刷子抓粉力好，非常适合打造眼部的立体感。<br>\r\n&nbsp;</p>\r\n\r\n<p>※包装盒可从品牌设计的普通<strong>“纸盒”</strong>和可选的特制<strong>「桐木盒（＋</strong></p>\n<div>\r\n                    <p style=\"text-align: center;\"><img alt=\"\" src=\"https://gigaplus.makeshop.jp/kydkyd/somellgarden/somellgarden_top.jpg\"><br>\r\n&nbsp;</p>\r\n\r\n<p style=\"text-align: center;\"><img alt=\"\" src=\"https://gigaplus.makeshop.jp/kydkyd/somellgarden/sgimg01.jpg\"><br>\r\n&nbsp;</p>\r\n\r\n<table style=\"width: 100%;\">\r\n<tbody>\r\n<tr>\r\n<td style=\"padding: 1.5em; vertical-align: top;\"><img alt=\"\" src=\"https://gigaplus.makeshop.jp/kydkyd/somellgarden/sgimg04.jpg\"></td>\r\n<td style=\"padding: 1.5em;\">\r\n<p style=\"margin: 0px 0px 1em;\"><img alt=\"\" src=\"https://gigaplus.makeshop.jp/kydkyd/somellgarden/sgimg02.jpg\"></p>\r\n\r\n<p style=\"font-size: 12px;\">由中国经济产业局主办，与研究机构和设计师合作，以“可爱之物”为理念进行商品开发的“可爱之物研究会”。<br>\r\nsomell garden正是在这一举措中，源自当地广岛女性设计师的以下提案而诞生。</p>\r\n\r\n<p style=\"margin: 1em 0px;\"><img alt=\"\" src=\"https://gigaplus.makeshop.jp/kydkyd/somellgarden/sgimg03.jpg\"></p>\r\n\r\n<p style=\"font-size: 12px;\">彩妆产品的名称中，使用了许多桃子、橙子等果实的名字。<br>\r\n那么，如果给化妆刷也加入果实的意象呢？比如，能以仿佛用脸颊轻蹭果实般的心情将刷子触碰肌肤……如果能像“染花”一样将果实的颜色印染在肌肤上……。<br>\r\n或许就能制作出带着这样美好心情每天早晨化妆的刷子。</p>\r\n\r\n<p style=\"margin: 1em 0px;\"><img alt=\"\" src=\"https://gigaplus.makeshop.jp/kydkyd/somellgarden/sgimg05.jpg\"></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<table style=\"width: 100%; margin-top: 20px;\">\r\n<tbody>\r\n<tr>\r\n<td style=\"padding: 1.5em;\">\r\n<p style=\"margin: 0px 0px 1em;\"><img alt=\"\" src=\"https://gigaplus.makeshop.jp/kydkyd/somellgarden/sgimg06.jpg\"></p>\r\n\r\n<p style=\"font-size: 12px;\">不仅呈现出如果实染就般的自然色彩，例如桃子是中央凹陷的心形，蓝莓是紧凑圆润的刷尖，在确保易用性的基础上，笔尖形状也各自以果实为意象进行设计。</p>\r\n\r\n<p style=\"margin: 1em 0px;\"><img alt=\"\" src=\"https://gigaplus.makeshop.jp/kydkyd/somellgarden/sgimg07.jpg\"></p>\r\n\r\n<p style=\"font-size: 12px;\">刷杆根据每种果实的颜色搭配相应的天然木材。<br>\r\n为了让温暖不仅传达给脸部，也温柔地传递给双手，我们对刷杆的触感也精益求精。</p>\r\n\r\n<p style=\"margin: 1em 0px;\"><img alt=\"\" src=\"https://gigaplus.makeshop.jp/kydkyd/somellgarden/sgimg08.jpg\"></p>\r\n\r\n<p style=\"font-size: 12px;\">从作为化妆刷生命的原毛筛选开始，追求极致肌肤触感，采用机械生产无法实现的不剪毛尖工艺，每一支都手工制作。。</p>\r\n</td>\r\n<td style=\"padding: 1.5em; vertical-align: top;\"><img alt=\"\" src=\"https://gigaplus.makeshop.jp/kydkyd/somellgarden/sgimg09.jpg\"></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n                </div>",
