  "desc": "仅使用优质山羊毛、细光峰制成的最高级Yoshiki系列 采用圆形设计，可360度充分体验优质山羊毛的弹性和亲肤触感。 这款化妆刷融入了书法毛笔的技艺，全部手工制作，彻底去除没有笔尖的毛，因此没有刺痛感。 手柄采用天然木材，木纹隐约可见，设计富有高级感。 ■蜜粉刷 刷毛密集且富有弹性，所有面均可使用，轻松打造光泽感。 圆形设计可从360度各种角度使用，不易涂得过厚，易于调整。 ■腮红刷 抓粉力和显色度都很好的化妆刷，可以随心所欲地上腮红并晕染。 ■眼影刷 L 如同书法毛笔般聚拢性好的化妆刷，可以将眼影涂在眼窝等理想位置，自然打造渐变效果。 ■眼影刷 M 如同书法笔般聚拢性良好的刷子，可将眼影精准地点缀在眼皮上想要强调的位置。 ■唇刷＆眼线刷 如同书法笔般聚拢性良好的刷子，可随心所欲地描绘眼线和唇线。",
