  "detailHtml": "<p><span style=\"color: rgb(255, 0, 0);\"><strong>以日本传统文化——榻榻米包边制作的收纳袋</strong></span></p>\r\n\r\n<p><br>\r\n榻榻米包边（畳縁）是指缝在榻榻米边缘、用于加固和装饰的布料。<br>\r\n如今其设计花样丰富，不仅用于榻榻米，也常被用作小物件的材料，广受欢迎。<br>\r\n这是一款将一支支手工制作、怀旧又新颖的「榻榻米包边」制成的收纳袋。</p>\r\n\r\n<p><br>\r\n<strong>收纳袋有4种款式可供选择。</strong></p>\r\n\r\n<ul>\r\n<li style=\"text-align: left;\">　/市松</li>\r\n<li style=\"text-align: left;\">　/红梅</li>\r\n<li style=\"text-align: left;\">　/黑梅</li>\r\n<li style=\"text-align: left;\">　/玫瑰（无库存）</li>\r\n</ul>",
