  "desc": "KOYUDO collection最高端系列诞生 精选灰松鼠毛中混入优质山羊毛，再融入晃祐堂制笔工艺中诞生的“错位技术”，打造出柔软中兼具适度弹性的全新化妆刷。 这款蜜粉刷采用超大圆平形状，刷毛密集且富有弹性，轻松打造光泽感。 可用于蜜粉和粉底液，不易涂厚，便于调整用量。 这款融入制笔技术的化妆刷，由工匠一根一根精心手工制作。 天然毛中原本就有无毛尖或粗糙的毛，需通过肉眼和指尖触感将其剔除。 由此打造出不扎脸、亲肤舒适的化妆刷。",
