  "desc": "补货到货！！ 由笔司植松藤盛亲手打造的最高峰熊野笔与 莳绘联袂呈现的顶级臻品，数量限定发售 采用山羊毛中最柔软的毛种“细微光峰”，毛质顺滑，拥有普通山羊毛所不具备的光泽。 晃祐堂的化妆刷采用源自书法毛笔技艺的独家工艺制作而成。 笔尖直径为Φ30mm，是蜜粉刷中最大的尺寸。这款化妆刷采用密度极高的顶级山羊毛，让您体验肌肤上的绝佳触感。 刷杆采用樱木制作，樱花图案的“莳绘”尽显高级质感。 您可选择樱花图案。 ●枝樱（Branch cherry Blossoms） ● 散樱（Scattered cherry Blossoms）已售罄 即使您已完成购买手续，我们也将取消订单。 ※发货可能需要一些时间。可能无法在您指定的日期和时间送达，敬请谅解。 莳绘作家简介 大下昇一郎 地方产业振兴莳绘展连续获奖 致力于莳绘技法的研究，追求古老传统莳绘与现代莳绘的融合，以传统气质与崭新技法探寻山中涂未来的发展方向。",
