  "desc": "由笔司植松藤盛亲手打造的最高峰熊野笔与 莳绘联袂呈现的顶级臻品，数量限定发售 采用山羊毛中最柔软的毛种“细微光峰”，毛质顺滑，拥有普通山羊毛所不具备的光泽。 晃祐堂的化妆刷采用源自书法毛笔技艺的独家工艺制作而成。 这款化妆刷采用顶级山羊毛，密度高，能让肌肤体验绝佳触感。 刷杆采用樱木制作，樱花图案的“莳绘”尽显高级质感。 您可选择樱花图案。 ●枝樱（Branch cherry Blossoms） ●散落樱花（Scattered cherry Blossoms）【无库存】 即使您已完成购买手续，我们也将取消订单 ●附桐木盒（15.0×8.0×4.0） 莳绘作家简介 大下昇一郎 地方产业振兴莳绘展连续获奖 致力于莳绘技法的研究，追求古老传统莳绘与现代莳绘的融合，以传统气质与崭新技法探寻山中涂未来的发展方向。",
  "detail": "由笔司植松藤盛亲手打造的最高峰熊野笔与 莳绘联袂呈现的顶级臻品，数量限定发售 采用山羊毛中最柔软的毛种“细微光峰”，毛质顺滑，拥有普通山羊毛所不具备的光泽。 晃祐堂的化妆刷采用源自书法毛笔技艺的独家工艺制作而成。 这款化妆刷采用顶级山羊毛，密度高，能让肌肤体验绝佳触感。 刷杆采用樱木制作，樱花图案的“莳绘”尽显高级质感。 您可选择樱花图案。 ●枝樱（Branch cherry Blossoms） ●散落樱花（Scattered cherry Blossoms）【无库存】 即使您已完成购买手续，我们也将取消订单 ●附桐木盒（15.0×8.0×4.0） 莳绘作家简介 大下昇一郎 地方产业振兴莳绘展连续获奖 致力于莳绘技法的研究，追求古老传统莳绘与现代莳绘的融合，以传统气质与崭新技法探寻山中涂未来的发展方向。 形状 圆头 毛质 山羊毛 细微光峰 出 锋 40mm 全长 118mm",
  "detailHtml": "<p><span style=\"color: rgb(255, 0, 0);\"><strong>由笔司植松藤盛亲手打造的最高峰熊野笔与<br>\r\n莳绘联袂呈现的顶级臻品，数量限定发售 </strong></span></p>\r\n\r\n<p>　<br>\r\n采用山羊毛中最柔软的毛种“细微光峰”，毛质顺滑，拥有普通山羊毛所不具备的光泽。<br>\r\n晃祐堂的化妆刷采用源自书法毛笔技艺的独家工艺制作而成。</p>\r\n\r\n<p>　</p>\r\n\r\n<p>这款化妆刷采用顶级山羊毛，密度高，能让肌肤体验绝佳触感。<br>\r\n刷杆采用樱木制作，樱花图案的“莳绘”尽显高级质感。</p>\r\n\r\n<p>　</p>\r\n\r\n<p><span style=\"color: rgb(255, 0, 0);\">您可选择樱花图案。</span><br>\r\n●枝樱（Branch cherry Blossoms）<br>\r\n<strong><span style=\"color: rgb(255, 0, 0);\">●散落樱花（Scattered cherry Blossoms）【无库存】<br>\r\n&nbsp;　即使您已完成购买手续，我们也将取消订单</span></strong><br>\r\n<br>\r\n●附桐木盒（15.0×8.0×4.0）</p>\r\n\r\n<p>　</p>\r\n\r\n<p><span style=\"color: rgb(255, 0, 0);\">莳绘作家简介</span><br>\r\n<strong>大下昇一郎</strong><br>\r\n地方产业振兴莳绘展连续获奖<br>\r\n致力于莳绘技法的研究，追求古老传统莳绘与现代莳绘的融合，以传统气质与崭新技法探寻山中涂未来的发展方向。</p>\r\n\r\n<p>　</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>形状</th>\r\n<td>圆头</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>\r\n<p>山羊毛　细微光峰</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>出　锋</th>\r\n<td>\r\n<p>40mm</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>\r\n<p>118mm</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\n<div>\r\n                    <img alt=\"細微光峰カブキブラシ\" src=\"https://gigaplus.makeshop.jp/kydkyd/mv/kabuki_banner.jpg\" style=\"width: 100%;\">\r\n                </div>",
