  "detailHtml": "<p><span style=\"color: rgb(255, 0, 0);\"><strong>仅使用优质山羊毛中的细光峰，采用柿涩染</strong></span><span style=\"color: rgb(255, 0, 0);\"><strong>系列。</strong></span></p>\r\n\r\n<p>采用触感格外的细光峰，并将笔尖以柿涩染染成宛如黄昏时分般怀旧的颜色。<br>\r\n<strong>【柿涩染】</strong><br>\r\n柿涩是自平安时代起传承至今的纯天然染料，具有抗菌效果，可用于日常各种场景。<br>\r\n随着时间推移，颜色逐渐渗透加深，形成深邃韵味，这也是其魅力之一<br>\r\n※因属于草木染的一种，清洗时可能会掉色<br>\r\n请享受越用越有变化的韵味。<br>\r\n※因手工染色加工，实物与图片颜色可能有所不同</p>\r\n\r\n<p>　</p>\r\n\r\n<p>笔尖采用细光峰（高级山羊毛）。蓬松的圆头形状，是蜜粉刷中毛量丰盈的一款。<br>\r\n可轻柔均匀地将粉铺于肌肤。<br>\r\n手柄采用天然木材，木纹隐约可见，设计富有高级感。</p>\r\n\r\n<p>　</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>形状</th>\r\n<td>\r\n<p>圆头</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>\r\n<p>山羊毛</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>出　锋</th>\r\n<td>\r\n<p>50mm</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>\r\n<p>165mm</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>",
