  "desc": "仅使用优质山羊毛中的细光峰，采用柿涩染 系列。 采用触感格外的细光峰，并将笔尖以柿涩染染成宛如黄昏时分般怀旧的颜色。 【柿涩染】 柿涩是自平安时代起传承至今的纯天然染料，具有抗菌效果，可用于日常各种场景。 随着时间推移，颜色逐渐渗透加深，形成深邃韵味，这也是其魅力之一。 ※因属于草木染的一种，清洗时可能会掉色 请享受越用越有变化的韵味 ※因手工染色加工，实物与图片颜色可能有所不同 笔尖采用细光峰（高级山羊毛）。 能够很好地延展和晕染粉末，打造自然的妆效。 手柄采用天然木材，木纹隐约可见，设计富有高级感。",
