  "desc": "推荐眼妆＆美润口罩套装 特别3件套 在口罩不可或缺的当下，防疫与美妆有这套就完美♪ 戴口罩时眼部更显突出，正是眼妆刷大显身手之时。 将眼妆所需化妆刷与抗菌＆滋润口罩组成套装。 ※口罩也可单独购买 【套装内容】 ●眼影刷 特点是尖端收拢的圆顶形状，可将眼影轻柔地晕染至眼周细小部位。 ●眉刷 与一般的眉刷相比，尺寸偏大是其特点，可以柔和地描绘眉毛。 ●抗菌＆保湿口罩 可反复使用，洗涤后纤维上的特定病毒数量减少99%以上！ 内层面料：保湿材质Oasis Road® 表层面料：在医院广泛使用的CLEANSE® ※Oasis Road®是ICHIBO的天然整理加工材质 ※CLEANSER/CLEANSE®是仓敷纺织的注册商标",
