  "detailHtml": "<div style=\"text-align: left;\"><span style=\"color: rgb(255, 0, 0);\"><strong>推荐眼妆＆美润口罩套装　特别3件套</strong></span></div>\r\n\r\n<div></div>\r\n\r\n<div style=\"text-align: left;\">\r\n<div style=\"text-align: left;\">在口罩不可或缺的当下，防疫与美妆有这套就完美♪<br>\r\n戴口罩时眼部更显突出，正是眼妆刷大显身手之时。<br>\r\n将眼妆所需化妆刷与抗菌＆滋润口罩组成套装。<br>\r\n※口罩也可单独购买<br>\r\n<br>\r\n【套装内容】　<br>\r\n●眼影刷<br>\r\n特点是尖端收拢的圆顶形状，可将眼影轻柔地晕染至眼周细小部位。<br>\r\n●眉刷<br>\r\n与一般的眉刷相比，尺寸偏大是其特点，可以柔和地描绘眉毛。<br>\r\n●抗菌＆保湿口罩<br>\r\n可反复使用，洗涤后纤维上的特定病毒数量减少99%以上！<br>\r\n内层面料：保湿材质Oasis Road&#174;<br>\r\n表层面料：在医院广泛使用的CLEANSE&#174;<br>\r\n※Oasis Road&#174;是ICHIBO的天然整理加工材质<br>\r\n※CLEANSER/CLEANSE&#174;是仓敷纺织的注册商标</div>\r\n\r\n<div style=\"text-align: left;\">\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>组 合</th>\r\n<td style=\"text-align: left;\">眼影刷　毛质：青马毛<br>\r\n形状：尖头　出穗：10mm　全长：130mm<br>\r\n眉刷　毛质：青马毛<br>\r\n形状：斜角　出穗：7mm　全长：127mm<br>\r\n口罩</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<br>\r\n&nbsp;",
