  "desc": "献给不断挑战新事物的你。 “La Fuga del Gatto”（猫的赋格）是以熊野笔技术为基础打造的100%合成纤维纯素化妆刷。 追求不逊于天然毛的使用感，也非常适合自然妆容。 刷毛尖端混合了植物来源的合成纤维，采用晃祐堂原创配比，包装使用以甘蔗榨渣为原料的甘蔗渣纸浆，是一款致力于SDGs的商品。 从五线谱中活力跃出的猫咪插画，寓意打破固有观念、挑战新事物。 蜡烛造型的蜜粉＆腮红刷，如同书法毛笔一样，笔尖的展开与聚拢收放自如，抓粉力也出众。轻松实现蓬松自然的妆效。",
  "detail": "献给不断挑战新事物的你。 “La Fuga del Gatto”（猫的赋格）是以熊野笔技术为基础打造的100%合成纤维纯素化妆刷。 追求不逊于天然毛的使用感，也非常适合自然妆容。 刷毛尖端混合了植物来源的合成纤维，采用晃祐堂原创配比，包装使用以甘蔗榨渣为原料的甘蔗渣纸浆，是一款致力于SDGs的商品。 从五线谱中活力跃出的猫咪插画，寓意打破固有观念、挑战新事物。 蜡烛造型的蜜粉＆腮红刷，如同书法毛笔一样，笔尖的展开与聚拢收放自如，抓粉力也出众。轻松实现蓬松自然的妆效。 形状 尖头 毛质 PTT＋PBT 出 锋 50mm 全长 165mm 纯素化妆刷与SDGs 纯素化妆刷是指不使用动物毛的化妆刷。 如今，作为熊野笔材料的动物毛获取逐年变得困难。 晃祐堂为了 让熊野笔这一文化得以永久传承， 将合成纤维向动物毛靠拢，打造出使用感毫不逊色的产品。 宛如未曾触碰般的新触感 刷毛尖端使用的合成纤维极细，仅0.07mm，触感极佳。 此外还混合了植物来源的合成纤维，能感受到更加宛如未触碰般的触感。 这款商品也深受化妆师好评。 包装采用甘蔗渣纸浆 甘蔗渣是榨糖后产生的农业副产品，在实现有限森林资源可持续利用方面， 是珍贵的生物质资源 。 “La Fuga del Gatto”的包装就采用了这种甘蔗渣纸浆。",
  "detailHtml": "<p><span style=\"color:#EE82EE;\"><strong>献给不断挑战新事物的你。</strong></span></p>\r\n\r\n<p><strong>“La Fuga del Gatto”（猫的赋格）是以熊野笔技术为基础打造的100%合成纤维纯素化妆刷。</strong><br>\r\n追求不逊于天然毛的使用感，也非常适合自然妆容。<br>\r\n刷毛尖端混合了植物来源的合成纤维，采用晃祐堂原创配比，包装使用以甘蔗榨渣为原料的甘蔗渣纸浆，是一款致力于SDGs的商品。<br>\r\n从五线谱中活力跃出的猫咪插画，寓意打破固有观念、挑战新事物。<br>\r\n<br>\r\n蜡烛造型的蜜粉＆腮红刷，如同书法毛笔一样，笔尖的展开与聚拢收放自如，抓粉力也出众。轻松实现蓬松自然的妆效。</p>\r\n\r\n<p>　</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>形状</th>\r\n<td>\r\n<p>尖头</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>\r\n<p>PTT＋PBT</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>出　锋</th>\r\n<td>\r\n<p>50mm</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>\r\n<p>165mm</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<p></p>\n<div>\r\n                    <div id=\"youtube-area\" style=\"margin-bottom: 20px;\"><iframe allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen=\"\" frameborder=\"0\" height=\"315\" src=\"https://www.youtube.com/embed/oq6ShMgIgo0\" title=\"YouTube video player\" width=\"560\"></iframe></div>\r\n\r\n<div style=\"text-align: left;\"><span style=\"color:#EE82EE;\"><strong>纯素化妆刷与SDGs</strong></span><br>\r\n纯素化妆刷是指不使用动物毛的化妆刷。<br>\r\n如今，作为熊野笔材料的动物毛获取逐年变得困难。<br>\r\n晃祐堂为了<span style=\"color:#FF0000;\"><u>让熊野笔这一文化得以永久传承，</u></span>将合成纤维向动物毛靠拢，打造出使用感毫不逊色的产品。<br>\r\n<span style=\"color:#EE82EE;\"><strong>宛如未曾触碰般的新触感</strong></span><br>\r\n刷毛尖端使用的合成纤维极细，仅0.07mm，触感极佳。<br>\r\n此外还混合了植物来源的合成纤维，能感受到更加宛如未触碰般的触感。<br>\r\n这款商品也深受化妆师好评。<br>\r\n<span style=\"color:#EE82EE;\"><strong>包装采用甘蔗渣纸浆</strong></span><br>\r\n甘蔗渣是榨糖后产生的农业副产品，在实现有限森林资源可持续利用方面，<span style=\"color:#FF0000;\">是珍贵的生物质资源</span>。<br>\r\n“La Fuga del Gatto”的包装就采用了这种甘蔗渣纸浆。</div>\r\n\r\n<div style=\"text-align: left;\"></div>\r\n\r\n                </div>",
