  "detailHtml": "<p><strong><span style=\"color: rgb(255, 0, 0);\">银狐毛〈银狐〉</span></strong><br>\r\n<strong>采用稀缺珍贵的银狐毛制成的顶级化妆刷</strong><br>\r\n<br>\r\n银狐毛兼具高级毛材“松鼠毛”的柔软与“山羊毛”适度的挺度。<br>\r\n严选被视为最优质的银黑毛色浓郁深邃的毛料。触感顺滑极致，为肌肤营造自然光泽。<br>\r\n<br>\r\n特点是如毛笔般前端尖锐的造型，能漂亮地将眼影涂至眼周细节部位。<br>\r\n<br>\r\n刷杆以樱木制成，枫叶纹样的“莳绘”尽显高级质感，堪称逸品。<br>\r\n请体验银狐毛特有的极致世界。</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>形状</th>\r\n<td>\r\n<p>尖头</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>\r\n<p>银狐毛</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>出　锋</th>\r\n<td>\r\n<p>15mm</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>\r\n<p>115mm</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\n<div>\r\n                    <div style=\"text-align: left;\"><span style=\"color: rgb(255, 0, 0);\"><strong>※<span style=\"font-size: 16px;\">自下单至发货约需1周左右时间，可能无法指定日期与时间，敬请谅解。</span></strong></span></div>\r\n\r\n                </div>",
