  "desc": "面部刷～世界三大美人～ 裕人砾翔×植松义贵 联名合作 裕人砾翔（Hiroto Rakusho）是日本代表性的箔艺术家。 植松义贵是在广岛县熊野町活动的日本首屈一指的笔匠。 通过两位的联名合作，诞生了前所未有的全球数量限定产品。 世界级箔艺术家裕人砾翔出生于京都西阵的纹样箔业世家，拥有罕见的天赋与技艺，是独一无二的箔艺术家。 植松义贵18岁进入制笔世界并潜心钻研。年纪轻轻便完成了供奉于正仓院的天平笔复刻版，是日本屈指可数的笔匠。三人作为艺术家在感性上、在创造造物价值的理念上彼此相通，遂决定联名合作，并立即着手制作试作品。 箔与笔的共演。除箔与笔的色调外，对笔触与使用感受的追求，二者互不妥协。为打造完美之作，反复商讨并多次试制。最终得以诞生。 逐支生产的100支限定版，每一支设计皆不相同，没有两支完全一样。当您拿起表情各异的面部刷的那一刻，各自的故事便由此开始。 衷心希望您能尽情享受两位技艺卓越的匠人交织而成的独一无二的世界。",
  "detail": "面部刷～世界三大美人～ 裕人砾翔×植松义贵 联名合作 裕人砾翔（Hiroto Rakusho）是日本代表性的箔艺术家。 植松义贵是在广岛县熊野町活动的日本首屈一指的笔匠。 通过两位的联名合作，诞生了前所未有的全球数量限定产品。 世界级箔艺术家裕人砾翔出生于京都西阵的纹样箔业世家，拥有罕见的天赋与技艺，是独一无二的箔艺术家。 植松义贵18岁进入制笔世界并潜心钻研。年纪轻轻便完成了供奉于正仓院的天平笔复刻版，是日本屈指可数的笔匠。三人作为艺术家在感性上、在创造造物价值的理念上彼此相通，遂决定联名合作，并立即着手制作试作品。 箔与笔的共演。除箔与笔的色调外，对笔触与使用感受的追求，二者互不妥协。为打造完美之作，反复商讨并多次试制。最终得以诞生。 逐支生产的100支限定版，每一支设计皆不相同，没有两支完全一样。当您拿起表情各异的面部刷的那一刻，各自的故事便由此开始。 衷心希望您能尽情享受两位技艺卓越的匠人交织而成的独一无二的世界。 形状 圆头 毛质 山羊毛（细光峰） 出锋 约54mm 全长 约160mm 将克娄巴特拉散发的妖艳氛围赋予整支刷子。 毛的黄金色以她所生活的古埃及时代为意象，通过柿涩染与独特加工得以实现。 包裹刷子的包袱布采用的是100%真丝的正绢（shoken）绉绸。 这是代表包袱布的材料，是海外所没有的日本独有织物。纬线施以强捻，利用其回捻之力形成“皱缩”。正绢绉绸具有恰到好处的光泽与蓬松柔软的质感，是日本引以为傲的优质素材。 本商品将刷子比作人、将包袱布比作和服，以右前（先将右侧布料贴合自身肌肤的穿法）包裹方式提供。愿您如同珍视重要之人一般长久爱用。 （请勿洗涤包袱布） ●关于箔（金属件、刷杆部分） /请绝对不要用水或热水整体清洗。请勿在潮湿状态下长时间放置。 /请注意，置于高温场所或受阳光直射，或使用稀释剂、挥发油等，会导致变色、变形。 /在高温、潮湿场所长时间放置会导致发霉或金属生锈，请保管于温度、湿度较低且通风良好之处。 /因手工制作，色调与形状可能与照片有所不同。 /本品在天然木材上施以本金箔粘合加工。使用过程中因摩擦等，箔会逐渐剥落，敬请谅解。 /本品因商品特性，做工精细，请勿施加强力。施加强力会导致破损。从高处掉落或用尖锐物强力触碰会导致划痕或剥落。 /本品使用金属。金属过敏者请勿使用。 其他：本品是根据用途与功能性等考量而制作的。请勿用于目的以外的用途。",
  "detailHtml": "<div><strong>面部刷～世界三大美人～</strong><br>\r\n<br>\r\n<strong>裕人砾翔×植松义贵 联名合作</strong><br>\r\n&nbsp;</div>\r\n\r\n<div style=\"text-align: left;\">裕人砾翔（Hiroto Rakusho）是日本代表性的箔艺术家。<br>\r\n植松义贵是在广岛县熊野町活动的日本首屈一指的笔匠。<br>\r\n通过两位的联名合作，诞生了前所未有的全球数量限定产品。<br>\r\n<br>\r\n世界级箔艺术家裕人砾翔出生于京都西阵的纹样箔业世家，拥有罕见的天赋与技艺，是独一无二的箔艺术家。<br>\r\n<br>\r\n植松义贵18岁进入制笔世界并潜心钻研。年纪轻轻便完成了供奉于正仓院的天平笔复刻版，是日本屈指可数的笔匠。三人作为艺术家在感性上、在创造造物价值的理念上彼此相通，遂决定联名合作，并立即着手制作试作品。<br>\r\n<br>\r\n箔与笔的共演。除箔与笔的色调外，对笔触与使用感受的追求，二者互不妥协。为打造完美之作，反复商讨并多次试制。最终得以诞生。<br>\r\n&nbsp;<br>\r\n逐支生产的100支限定版，每一支设计皆不相同，没有两支完全一样。当您拿起表情各异的面部刷的那一刻，各自的故事便由此开始。<br>\r\n&nbsp;<br>\r\n衷心希望您能尽情享受两位技艺卓越的匠人交织而成的独一无二的世界。<br>\r\n&nbsp;</div>\r\n\r\n<div>&nbsp; &nbsp; &nbsp;&nbsp;</div>\r\n\r\n<div style=\"text-align: left;\"></div>\r\n\r\n<table align=\"center\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" class=\"sstable\" style=\"width: 500px;\">\r\n<tbody>\r\n<tr>\r\n<th scope=\"row\">形状</th>\r\n<td>圆头</td>\r\n</tr>\r\n<tr>\r\n<th scope=\"row\">毛质</th>\r\n<td>山羊毛（细光峰）</td>\r\n</tr>\r\n<tr>\r\n<th scope=\"row\">出锋</th>\r\n<td>约54mm</td>\r\n</tr>\r\n<tr>\r\n<th scope=\"row\">全长</th>\r\n<td>约160mm</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<div style=\"text-align: left;\"><br>\r\n将克娄巴特拉散发的妖艳氛围赋予整支刷子。<br>\r\n毛的黄金色以她所生活的古埃及时代为意象，通过柿涩染与独特加工得以实现。<br>\r\n<br>\r\n包裹刷子的包袱布采用的是100%真丝的正绢（shoken）绉绸。<br>\r\n这是代表包袱布的材料，是海外所没有的日本独有织物。纬线施以强捻，利用其回捻之力形成“皱缩”。正绢绉绸具有恰到好处的光泽与蓬松柔软的质感，是日本引以为傲的优质素材。<br>\r\n本商品将刷子比作人、将包袱布比作和服，以右前（先将右侧布料贴合自身肌肤的穿法）包裹方式提供。愿您如同珍视重要之人一般长久爱用。<br>\r\n（请勿洗涤包袱布）<br>\r\n&nbsp;\r\n<p>●关于箔（金属件、刷杆部分）</p>\r\n\r\n<p>/请绝对不要用水或热水整体清洗。请勿在潮湿状态下长时间放置。</p>\r\n\r\n<p>/请注意，置于高温场所或受阳光直射，或使用稀释剂、挥发油等，会导致变色、变形。</p>\r\n\r\n<p>/在高温、潮湿场所长时间放置会导致发霉或金属生锈，请保管于温度、湿度较低且通风良好之处。</p>\r\n\r\n<p>/因手工制作，色调与形状可能与照片有所不同。</p>\r\n\r\n<p>/本品在天然木材上施以本金箔粘合加工。使用过程中因摩擦等，箔会逐渐剥落，敬请谅解。</p>\r\n\r\n<p>/本品因商品特性，做工精细，请勿施加强力。施加强力会导致破损。从高处掉落或用尖锐物强力触碰会导致划痕或剥落。</p>\r\n\r\n<p>/本品使用金属。金属过敏者请勿使用。</p>\r\n\r\n<p>其他：本品是根据用途与功能性等考量而制作的。请勿用于目的以外的用途。</p>\r\n</div>",
