  "detailHtml": "<p><span style=\"color:#FF0000;\"><strong>人气SOMELL GARDEN系列推出洁面刷！</strong></span><br>\r\n采用耐久性强、触感柔软的PBT与山羊毛。<br>\r\n通过混合不同长度的毛材，能带入更多空气，起泡效果出众！<br>\r\n接触肌肤也不会刺痛，可舒适地清洗整个脸部，还能期待按摩效果。<br>\r\n手柄采用天然木材【胡桃木】，营造出高级感，也是送礼佳品！<br>\r\n<br>\r\n使用后请将刷子充分冲洗干净并去除水分，放在通风良好的地方晾干。</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>形状</th>\r\n<td>\r\n<p>圆头</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td style=\"text-align: left;\">山羊毛/聚酯纤维</td>\r\n</tr>\r\n<tr>\r\n<th>出　锋</th>\r\n<td style=\"text-align: left;\">35mm</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td style=\"text-align: left;\">70mm</td>\r\n</tr>\r\n</tbody>\r\n</table>\n<div>\r\n                    <iframe allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen=\"\" frameborder=\"0\" height=\"315\" src=\"https://www.youtube.com/embed/3Er_s-NSUMA\" title=\"YouTube video player\" width=\"560\"></iframe>\r\n<h2 style=\"text-align: center;\"></h2>\r\n\r\n<h2><span style=\"font-size: 20px;\">刷毛柔软，温和洗净肌肤，<br>\r\n连毛孔深处的污垢也能彻底清除！</span></h2>\r\n\r\n<p><br>\r\n如果您正为毛孔污垢和肌肤暗沉烦恼，也许是因为污垢没有彻底洗净！<br>\r\n<br>\r\n为了清除手洗无法洗净的污垢，用刷子很有效！<br>\r\n用刷子充分打出细腻泡沫，在泡沫上用刷子清洗，既能彻底清除毛孔污垢，又不会过度清洁，对肌肤刺激小，实现美肌洁面/美肌身体清洁。<br>\r\n&nbsp;</p>\r\n\r\n<h3>保养方法</h3>\r\n\r\n<div style=\"text-align: left;\">（1）首先将笔尖上的泡沫/洁面产品充分冲洗干净。<br>\r\n（2）从笔尖根部向毛尖方向，充分挤干水分。<br>\r\n　　（拧的时候不要扭转，否则会导致掉毛，请将毛捋直后挤干。）<br>\r\n（3）握住刷杆部分，将笔尖残留的水甩掉。<br>\r\n　　 &nbsp;笔尖可能会散开，但无需整理形状。<br>\r\n（4）放在毛巾等上面晾干。（最好放在避免直射阳光、通风良好的阴凉处）<br>\r\n&nbsp;</div>\r\n\r\n<p><span style=\"color: rgb(255, 0, 0);\"><strong>※注意事项</strong></span></p>\r\n\r\n<p>如果保持湿润状态，或沾有泡沫/洁面产品放置不管，会滋生霉菌，并导致断毛/掉毛/异味。</p>\r\n\r\n<p>想要长久使用，使用后的保养很重要</p>\r\n\r\n                </div>",
