  "desc": "汇集了对肌肤有益的物品，是送礼佳选的套装。 ※附在线限定礼盒包装",
  "detail": "汇集了对肌肤有益的物品，是送礼佳选的套装。 ※附在线限定礼盒包装 洁面刷 形状 扁平型 毛质 山羊毛/聚酯纤维 出 锋 35mm 全长 70mm 鼻部洁面刷 形状 心形 毛质 山羊毛 出 锋 17mm 全长 107mm 酒粕生皂 容量 80g 面巾 尺寸 约30cm × 80cm 材质 棉 包装盒 尺寸 约20cm×15cm×8cm 材质 桐木盒 ●洁面刷 晃祐堂原创双层结构制成的洁面刷，在肥皂上轻轻打圈即可产生浓密泡沫，柔软的笔尖能温和洗去毛孔污垢。 使用后请将刷子充分冲洗干净并去除水分，放在通风良好的地方晾干。 ※附带专用刷架 ●鼻部洁面刷 柔软的山羊毛能深入鼻翼周围难以清洁的凹陷处，温和洗净污垢。 使用后请将刷子充分冲洗干净并去除水分，放在通风良好的地方晾干。 ●酒粕生皂 凝聚美肌之源——酒粕与日本酒成分的自然派肥皂。 采用不加热的冷制工艺，原料成分以自然状态制成肥皂。 该工艺约需60天制造，因此无法大量生产。 但以这种方式精心制作的肥皂，完整保留了优质原料的成分与矿物质。 ●丝蛋白加工面巾 采用比普通毛巾所用纱线细约一半的“40号单纱”高密度织成，增加了与肌肤的接触面积，能更好地擦去肌肤污垢与水分。 经过丝蛋白加工，对肌肤温和，也可期待美容效果。 ※丝蛋白：主要将丝成分分解提取出的称为丝素蛋白的蛋白质，也是造就丝绸触感的主要成分",
  "detailHtml": "<p>汇集了对肌肤有益的物品，是送礼佳选的套装。</p>\r\n\r\n<p><span style=\"color: rgb(255, 0, 0);\"><strong>※附在线限定礼盒包装</strong></span></p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th colspan=\"2\">洁面刷</th>\r\n</tr>\r\n<tr>\r\n<th>形状</th>\r\n<td>扁平型</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>山羊毛/聚酯纤维</td>\r\n</tr>\r\n<tr>\r\n<th>出　锋</th>\r\n<td>35mm</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>70mm</td>\r\n</tr>\r\n<tr>\r\n<th colspan=\"2\">鼻部洁面刷</th>\r\n</tr>\r\n<tr>\r\n<th>形状</th>\r\n<td>心形</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>山羊毛</td>\r\n</tr>\r\n<tr>\r\n<th>出　锋</th>\r\n<td>17mm</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>107mm</td>\r\n</tr>\r\n<tr>\r\n<th colspan=\"2\">酒粕生皂</th>\r\n</tr>\r\n<tr>\r\n<th>容量</th>\r\n<td>80g</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th colspan=\"2\">面巾</th>\r\n</tr>\r\n<tr>\r\n<th>尺寸</th>\r\n<td>约30cm　 × 　80cm</td>\r\n</tr>\r\n<tr>\r\n<th>材质</th>\r\n<td>棉</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th colspan=\"2\">包装盒</th>\r\n</tr>\r\n<tr>\r\n<th>尺寸</th>\r\n<td>约20cm×15cm×8cm</td>\r\n</tr>\r\n<tr>\r\n<th>材质</th>\r\n<td>桐木盒</td>\r\n</tr>\r\n</tbody>\r\n</table>\n<div>\r\n                    <div style=\"text-align: left;\">●洁面刷<br>\r\n晃祐堂原创双层结构制成的洁面刷，在肥皂上轻轻打圈即可产生浓密泡沫，柔软的笔尖能温和洗去毛孔污垢。<br>\r\n使用后请将刷子充分冲洗干净并去除水分，放在通风良好的地方晾干。<br>\r\n※附带专用刷架<br>\r\n<br>\r\n●鼻部洁面刷<br>\r\n柔软的山羊毛能深入鼻翼周围难以清洁的凹陷处，温和洗净污垢。<br>\r\n使用后请将刷子充分冲洗干净并去除水分，放在通风良好的地方晾干。<br>\r\n<br>\r\n●酒粕生皂<br>\r\n凝聚美肌之源——酒粕与日本酒成分的自然派肥皂。<br>\r\n采用不加热的冷制工艺，原料成分以自然状态制成肥皂。<br>\r\n该工艺约需60天制造，因此无法大量生产。<br>\r\n但以这种方式精心制作的肥皂，完整保留了优质原料的成分与矿物质。<br>\r\n<br>\r\n●丝蛋白加工面巾<br>\r\n采用比普通毛巾所用纱线细约一半的“40号单纱”高密度织成，增加了与肌肤的接触面积，能更好地擦去肌肤污垢与水分。<br>\r\n经过丝蛋白加工，对肌肤温和，也可期待美容效果。<br>\r\n※丝蛋白：主要将丝成分分解提取出的称为丝素蛋白的蛋白质，也是造就丝绸触感的主要成分</div>\r\n\r\n<div style=\"text-align: left;\"></div>\r\n\r\n                </div>",
