  "desc": "传统工艺品产业振兴协会主办 2020年度传统工艺品公募展 入选为入选作品 目前订单较多，发货需要2～3周时间。 无法指定到货日期和时间，敬请谅解。 毛量充足的“花型身体刷”登场。 采用柔软的山羊毛，以与化妆刷相同的【不剪笔尖制法】制作，接触肌肤也不会刺痛，可舒适地清洗全身，还可期待按摩效果。 笔尖蓬松且具有适度的弹性，很多人反馈“光是触摸就很治愈”，是一款亲肤感极佳的身体刷。 凹凸部分能带入空气，使泡沫更细腻并加快起泡速度。 手柄采用天然木材【胡桃木】，营造出高级感，也是送礼佳品！ 手柄部分可选择“带柄”或“无柄”。 主体设有凹槽，女性也易于握持的设计。",
  "detail": "传统工艺品产业振兴协会主办 2020年度传统工艺品公募展 入选为入选作品 目前订单较多，发货需要2～3周时间。 无法指定到货日期和时间，敬请谅解。 毛量充足的“花型身体刷”登场。 采用柔软的山羊毛，以与化妆刷相同的【不剪笔尖制法】制作，接触肌肤也不会刺痛，可舒适地清洗全身，还可期待按摩效果。 笔尖蓬松且具有适度的弹性，很多人反馈“光是触摸就很治愈”，是一款亲肤感极佳的身体刷。 凹凸部分能带入空气，使泡沫更细腻并加快起泡速度。 手柄采用天然木材【胡桃木】，营造出高级感，也是送礼佳品！ 手柄部分可选择“带柄”或“无柄”。 主体设有凹槽，女性也易于握持的设计。 花形身体刷（无柄） 毛质 山羊毛/聚酯纤维 毛长 33mm 全长 80mm 包装盒 专用BOX（80mm×80mm×75mm） 【使用方法】 将笔尖用热水浸湿，沾取肥皂（固体、液体均可）揉合约10秒，打圈或揉搓使其充分起泡。 打圈按摩般轻柔清洗。 【使用后】 使用后请用流水充分冲洗至根部，并挤干水分。 请勿放置在潮湿处，应在干燥的地方充分晾干。（最好放在避免阳光直射、通风良好的阴凉处） 【使用注意事项】 使用天然皂可以延长笔尖寿命。 （通常约1年）",
  "detailHtml": "<p style=\"text-align: center;\"><strong>传统工艺品产业振兴协会主办<br>\r\n2020年度传统工艺品公募展</strong><br>\r\n<span style=\"color: rgb(255, 0, 0);\"><strong>入选为入选作品</strong></span></p>\r\n\r\n<p>　</p>\r\n\r\n<p style=\"text-align: center;\"><span style=\"color:#ff0000;\"><strong><span style=\"background-color:#ffffcc;\">目前订单较多，发货需要2～3周时间。<br>\r\n无法指定到货日期和时间，敬请谅解。</span></strong></span></p>\r\n\r\n<p><br>\r\n毛量充足的“花型身体刷”登场。</p>\r\n\r\n<p>采用柔软的山羊毛，以与化妆刷相同的【不剪笔尖制法】制作，接触肌肤也不会刺痛，可舒适地清洗全身，还可期待按摩效果。</p>\r\n\r\n<p>笔尖蓬松且具有适度的弹性，很多人反馈“光是触摸就很治愈”，是一款亲肤感极佳的身体刷。</p>\r\n\r\n<p>凹凸部分能带入空气，使泡沫更细腻并加快起泡速度。</p>\r\n\r\n<p>　</p>\r\n\r\n<p>手柄采用天然木材【胡桃木】，营造出高级感，也是送礼佳品！<br>\r\n　</p>\r\n\r\n<p><strong>手柄部分可选择“带柄”或“无柄”。<br>\r\n主体设有凹槽，女性也易于握持的设计。</strong></p>\r\n\r\n<p></p>\r\n\r\n<table class=\"sstable\" style=\"margin-bottom: 20px;\">\r\n<tbody>\r\n<tr>\r\n<th colspan=\"2\">花形身体刷（无柄）</th>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>山羊毛/聚酯纤维</td>\r\n</tr>\r\n<tr>\r\n<th>毛长</th>\r\n<td>33mm</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>80mm</td>\r\n</tr>\r\n<tr>\r\n<th>包装盒</th>\r\n<td>专用BOX（80mm×80mm×75mm）</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n</tr>\r\n<tr>\r\n</tr>\r\n</tbody>\r\n</table>\n<div>\r\n                    <iframe allow=\"accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen=\"\" frameborder=\"0\" height=\"315\" src=\"https://www.youtube.com/embed/7DBp5hIuv4w\" width=\"560\"></iframe><br>\r\n　\r\n<p><strong>【使用方法】</strong></p>\r\n\r\n<p>将笔尖用热水浸湿，沾取肥皂（固体、液体均可）揉合约10秒，打圈或揉搓使其充分起泡。</p>\r\n\r\n<p>打圈按摩般轻柔清洗。</p>\r\n\r\n<p>　</p>\r\n\r\n<p><strong>【使用后】</strong></p>\r\n\r\n<p>使用后请用流水充分冲洗至根部，并挤干水分。</p>\r\n\r\n<p>请勿放置在潮湿处，应在干燥的地方充分晾干。（最好放在避免阳光直射、通风良好的阴凉处）</p>\r\n　\r\n\r\n<p><strong>【使用注意事项】</strong></p>\r\n\r\n<p>使用天然皂可以延长笔尖寿命。<br>\r\n（通常约1年）</p>\r\n\r\n                </div>",
