  "desc": "柿涩染 熊野笔 5支套装 如黄昏时分般怀旧的色调 采用触感格外的细光峰（高级山羊毛），其笔尖经柿涩染染成如黄昏时分般怀旧的色调。 刷杆采用天然木材，木纹隐约可见，是富有高级感的设计。 【柿涩染】 柿涩是自平安时代以来传承至今的完全天然染料，具有抗菌效果，活跃于日常的各种场景。 随着时间推移，颜色逐渐渗透加深，形成深邃韵味，这也是其魅力之一。 ※因属草木染的一种，清洗时可能会掉色。 请享受越用越有变化的韵味。 ※因手工染色加工，实物与图片颜色可能有所不同 ※桐木盒的颜色、设计可能会有所变更",
