  "desc": "与深受众多当地粉丝喜爱的广岛东洋鲤鱼队携手合作，怀着共同振兴本地的愿望 毛量充足的“弯曲手套刷”登场！！ 山羊毛与合成纤维混合、毛量充足的手套刷 最适合用于棒球或垒球手套的上光打理♪ 除手套外，还可用于皮革制品（皮鞋、手提包）的上光，以及电脑、智能手机、平板电脑屏幕的清洁。",
