  "desc": "KOYUDO collection最高端系列诞生 精选灰松鼠毛中混入优质山羊毛，再融入晃祐堂制笔工艺中诞生的“错位技术”，打造出柔软中兼具适度弹性的全新化妆刷。 这款扇形刷采用斜角形状，连细节部位也能刷出光泽。 不仅可作为蜜粉刷使用，也可作为定妆刷使用。 这款融入制笔技术的化妆刷，由工匠一根一根精心手工制作。 天然毛中原本就有无毛尖或粗糙的毛，需通过肉眼和指尖触感将其剔除。 由此打造出不扎脸、亲肤舒适的化妆刷。",
