  "detailHtml": "<p>柯林斯基5支套装以珍贵的设计与精细的做工，每一支均由手工完成。这套融合了优雅与豪华的套装，将为您演绎更加华丽的风采。此外，柯林斯基5支套装也非常适合作为礼物。作为送给重要之人的赠礼，定会备受喜爱。请体验柯林斯基5支套装。</p>\r\n\r\n<p></p>\r\n\r\n<p>※使用时请注意保养与保管。为了长久使用，请用柔软的布轻轻擦拭，并避免存放在阳光直射或高温多湿的地方。</p>",
