  "desc": "采用稀有的白加拿大松鼠毛制成的高端化妆刷 市面上不常见的“白加拿大松鼠毛”原毛，抓粉力佳，兼具柔软与适度的挺度，触感极佳，能为肌肤带来自然光泽。 刷杆以樱木制成，樱花纹的“莳绘”展现出高级感，堪称逸品。 晃祐堂的化妆刷采用源自书法毛笔技艺的独家工艺制作而成。 请体验白加拿大松鼠毛化妆刷带来的前所未有的肌肤触感。",
