  "detailHtml": "<div style=\"text-align: left;\"><span style=\"color: rgb(255, 0, 0);\"><strong>采用稀有的白加拿大松鼠毛制成的高端化妆刷</strong></span><br>\r\n<br>\r\n市面上不常见的“白加拿大松鼠毛”原毛，抓粉力佳，兼具柔软与适度的挺度，触感极佳，能为肌肤带来自然光泽。<br>\r\n刷杆以樱木制成，樱花纹的“莳绘”展现出高级感，堪称逸品。<br>\r\n晃祐堂的化妆刷采用源自书法毛笔技艺的独家工艺制作而成。<br>\r\n请体验白加拿大松鼠毛化妆刷带来的前所未有的肌肤触感。<br>\r\n&nbsp;</div>\r\n\r\n<table align=\"center\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" class=\"sstable\" style=\"width: 500px;\">\r\n<tbody>\r\n<tr>\r\n<th scope=\"row\">形状</th>\r\n<td style=\"text-align: left;\">圆平</td>\r\n</tr>\r\n<tr>\r\n<th scope=\"row\">毛质</th>\r\n<td style=\"text-align: left;\">白加拿大松鼠毛</td>\r\n</tr>\r\n<tr>\r\n<th scope=\"row\">出锋</th>\r\n<td style=\"text-align: left;\">55mm</td>\r\n</tr>\r\n<tr>\r\n<th scope=\"row\">全长</th>\r\n<td style=\"text-align: left;\">145mm</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<br>\r\n<br>\r\n&nbsp;",
