  "detailHtml": "<p>【YT-5】眼影刷采用优质细光峰，其柔软与柔韧实现了对眼皮温和的触感。尖头造型能轻松打造细腻线条与自然渐变。</p><p>这款以熊野笔传统技艺完成的化妆刷，也深受专业人士喜爱。纤细的笔尖完美贴合眼部，能打造出理想的表情。一旦使用便爱不释手，堪称必备单品。</p><p>无论是在家还是外出，都能享受讲究的妆容。请务必入手这款提升您眼妆品质的单品。</p><p>这款眼影刷不仅赏心悦目，更在触感上精益求精。精致的设计也非常适合作为礼物。 </p><p>※请定期保养，以便长久爱用。</p><p style=\"text-align: center;\"><br>\n&nbsp;</p>\n\n<table class=\"sstable\">\n<tbody>\n<tr>\n<th>形状</th>\n<td>尖头</td>\n</tr>\n<tr>\n<th>毛质</th>\n<td>优质细光峰</td>\n</tr>\n<tr>\n<th>出　锋</th>\n<td>14mm</td>\n</tr>\n<tr>\n<th>全长</th>\n<td>154mm</td>\n</tr>\n</tbody>\n</table>",
