  "detailHtml": "<p><span style=\"color: rgb(255, 0, 0);\"><strong>KOYUDO collection中的最高峰系列</strong></span></p>\n\n<p><strong>精选优质顶级山羊毛混合其中，再融入由晃祐堂毛笔制造经验中诞生的“错位技术”，从而诞生了这款柔软中带有适度弹力的前所未有的化妆刷。<br>\n　</strong><br>\n作为蜜粉刷自不必说，能打造出理想的妆效，作为蜜粉刷其含粉量与发色俱佳，可随心所欲地扑粉晕染。<br>\n<br>\n这款融入制笔技术的化妆刷，由工匠一根一根精心手工制作。<br>\n天然毛中原本就有无毛尖或粗糙的毛，需通过肉眼和指尖触感将其剔除。<br>\n由此打造出不扎脸、亲肤舒适的化妆刷。</p>\n<p style=\"text-align: center;\"><br>\n&nbsp;</p>\n\n<table class=\"sstable\">\n<tbody>\n<tr>\n<th>形状</th>\n<td>圆平</td>\n</tr>\n<tr>\n<th>毛质</th>\n<td>优质细光峰/黑粗光峰</td>\n</tr>\n<tr>\n<th>出　锋</th>\n<td>50mm</td>\n</tr>\n<tr>\n<th>全长</th>\n<td>118mm</td>\n</tr>\n</tbody>\n</table>",
