  "detailHtml": "KOYUDO collection中的最高峰系列\n\n精选优质细光峰混合山羊毛，再融入由晃祐堂毛笔制造经验中诞生的“错位技术”，从而诞生了这款柔软中带有适度弹力的前所未有的化妆刷。\n\n如同毛笔般聚拢性良好的刷子，可将眼影涂抹到眼窝等理想部位，并自然晕染出渐变效果。\n\n这款融入毛笔技术的化妆刷，由工匠逐一手工精心制作。\n天然毛中原本就有无毛尖或粗糙的毛，需通过眼睛和指尖的感觉将其剔除。\n如此才能制作出不扎脸、肤感良好的化妆刷。<p style=\"text-align: center;\"><br>\n&nbsp;</p>\n\n<table class=\"sstable\">\n<tbody>\n<tr>\n<th>形状</th>\n<td>圆平</td>\n</tr>\n<tr>\n<th>毛质</th>\n<td>优质细光峰/黑粗光峰</td>\n</tr>\n<tr>\n<th>出　锋</th>\n<td>20mm</td>\n</tr>\n<tr>\n<th>全长</th>\n<td>115mm</td>\n</tr>\n</tbody>\n</table>",
