  "desc": "全新洁面刷诞生 泡沫细腻丰富，亲肤感出众。 采用触感舒适且富有弹性的山羊毛。",
  "detail": "全新洁面刷诞生 泡沫细腻丰富，亲肤感出众。 采用触感舒适且富有弹性的山羊毛。 形状 圆头 毛质 山羊毛/合成纤维 出 锋 40mm 全长 80mm 保养方法 （1）首先将笔尖上的泡沫/洁面产品充分冲洗干净。 （2）从笔尖根部向毛尖方向，充分挤干水分。 （拧的时候不要扭转，否则会导致掉毛，请将毛捋直后挤干。） （3）握住刷杆部分，甩去笔尖残留的水分。笔尖可能会散开，但无需整理形状。 （4）将笔尖朝下，悬挂晾干。 ※注意事项 如果保持湿润状态，或沾有泡沫/洁面产品放置不管，会滋生霉菌，并导致断毛/掉毛/异味。 想要长久使用，使用后的保养十分重要。",
  "detailHtml": "<p><span style=\"color: rgb(255, 0, 0);\"><strong>全新洁面刷诞生</strong></span><br>\n<br>\n泡沫细腻丰富，亲肤感出众。<br>\n采用触感舒适且富有弹性的山羊毛。<br>\n&nbsp;<br>\n\n\n<table class=\"sstable\">\n<tbody>\n<tr>\n<th>形状</th>\n<td>\n<p>圆头</p>\n</td>\n</tr>\n<tr>\n<th>毛质</th>\n<td>山羊毛/合成纤维</td>\n</tr>\n<tr>\n<th>出　锋</th>\n<td>40mm</td>\n</tr>\n<tr>\n<th>全长</th>\n<td>80mm</td>\n</tr>\n</tbody>\n</table>\n\r\n                    </p>\n<div>\r\n                    <div style=\"text-align: left;\"><span style=\"color: rgb(255, 0, 0);\"><strong>保养方法</strong></span><br>\r\n（1）首先将笔尖上的泡沫/洁面产品充分冲洗干净。<br>\r\n（2）从笔尖根部向毛尖方向，充分挤干水分。<br>\r\n（拧的时候不要扭转，否则会导致掉毛，请将毛捋直后挤干。）<br>\r\n（3）握住刷杆部分，甩去笔尖残留的水分。笔尖可能会散开，但无需整理形状。<br>\r\n（4）将笔尖朝下，悬挂晾干。<br>\r\n&nbsp;<br>\r\n<strong>※注意事项</strong><br>\r\n如果保持湿润状态，或沾有泡沫/洁面产品放置不管，会滋生霉菌，并导致断毛/掉毛/异味。<br>\r\n想要长久使用，使用后的保养十分重要。</div>\r\n\r\n<div style=\"text-align: left;\"></div>\r\n\r\n                </div>",
