  "desc": "回收中小学使用过的牵牛花塑料花盆，升级再造为熊野笔刷杆部分的SDGs产品 笔尖自然采用熊野笔工艺逐支精心制作，特点是聚拢性极佳。 此外，寓意合格的五角形刷杆部分融入德岛天然蓝染，呈现JAPAN BLUE“KACHIIRO”。本产品运用德岛天然蓝染表现“KACHIIRO”（褐色），可作为“吉祥之物”用于馈赠等用途购买。 “KACHIIRO”（褐色）是指…… 昔日战国时代的武将们，在铠甲之下身着“褐色”蓝染衣物，不仅因蓝染本身的抗菌、防虫效果，更将其作为带来胜负运、助战取胜的“胜色”而讨吉利、备受珍视，是一种吉祥的颜色。 JAPAN BLUE 熊野笔 \"KACHIIRO\" 由PHI株式会社与株式会社晃祐堂共创项目开发。 → 点击此处 毛质：山羊毛+再生聚酯毛 出穗：25mm×Φ7mm 全长：全长：207mm、重量：约8g",
