  "desc": "回收中小学使用过的牵牛花塑料花盆，升级再造为熊野笔刷杆部分的SDGs产品。本套装包含化妆中使用频率较高的腮红、眼影L、眼影S三支，笔尖自然采用熊野笔工艺逐支精心制作，特点是亲肤感好、显色佳。 此外，刷杆部分融入德岛天然蓝染，呈现JAPAN BLUE“KACHIIRO”。本产品运用德岛天然蓝染表现“KACHIIRO”（褐色），可作为“吉祥之物”用于馈赠等用途购买。 “KACHIIRO”（褐色）是指…… 昔日战国时代的武将们，在铠甲之下身着“褐色”蓝染衣物，不仅因蓝染本身的抗菌、防虫效果，更将其作为带来胜负运、助战取胜的“胜色”而讨吉利、备受珍视，是一种吉祥的颜色。 JAPAN BLUE 熊野笔 \"KACHIIRO\" 由PHI株式会社与株式会社晃祐堂共创项目开发。 → 点击此处 毛质/腮红：山羊毛、眼影L：山羊毛、眼影S：山羊毛 出穗/腮红：35mm、眼影L：15mm、眼影S：12mm 全长/腮红：140mm、眼影L：、眼影S：135mm",
